{
  "name": "surfing-pelican",
  "version": "1.0.0",
  "description": "Animated non-interactive surfing pelican in three.js",
  "type": "module",
  "private": true,
  "scripts": {
    "check": "esbuild main.js --bundle --format=esm --outfile=/dev/null"
  },
  "dependencies": {
    "three": "^0.170.0"
  },
  "devDependencies": {
    "esbuild": "^0.24.0"
  }
}

import * as THREE from 'three';

// Shared ocean wave function (also used to float the board, spray, camera...).
export function waveHeight(x, z, t) {
  return (
    1.35 * Math.sin(z * 0.10 - t * 0.75) + // main rolling swell
    0.45 * Math.sin(z * 0.23 - t * 1.35 + x * 0.06) + // secondary chop
    0.30 * Math.sin(x * 0.16 + t * 0.55) + // cross swell
    0.18 * Math.sin((x * 0.7 + z) * 0.14 + t * 1.05) // detail
  );
}

export function createWater() {
  const SIZE = 170;
  const SEGS = 110;
  const geometry = new THREE.PlaneGeometry(SIZE, SIZE, SEGS, SEGS);
  geometry.rotateX(-Math.PI / 2); // lie flat in XZ, displace Y

  const position = geometry.attributes.position;
  const count = position.count;
  const colors = new Float32Array(count * 3);
  geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  position.setUsage(THREE.DynamicDrawUsage);
  geometry.attributes.color.setUsage(THREE.DynamicDrawUsage);

  const material = new THREE.MeshStandardMaterial({
    vertexColors: true,
    flatShading: true, // derivative-based facet normals, no recompute needed
    roughness: 0.5,
    metalness: 0.05,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;

  const base = position.array.slice(); // static x/z of each vertex
  const deep = new THREE.Color('#0b5e78');
  const shallow = new THREE.Color('#31c3b0');
  const foam = new THREE.Color('#f4f9f7');
  const c = new THREE.Color();

  function update(t) {
    const p = position.array;
    for (let i = 0; i < count; i++) {
      const ix = i * 3;
      const x = base[ix];
      const z = base[ix + 2];
      const h = waveHeight(x, z, t);
      p[ix + 1] = h;
      // tint: deeper in troughs, lighter on rises, white foam on crests
      const hN = THREE.MathUtils.clamp(h * 0.42 + 0.5, 0, 1);
      c.copy(deep).lerp(shallow, hN);
      const f = THREE.MathUtils.smoothstep(h, 0.95, 1.45);
      if (f > 0) c.lerp(foam, f);
      colors[ix] = c.r;
      colors[ix + 1] = c.g;
      colors[ix + 2] = c.b;
    }
    position.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
  }

  update(0);
  return { mesh, update };
}

import * as THREE from 'three';

// Golden-hour gradient sky dome with a soft sun disc + glow (all in the shader).
export function createSky() {
  const geo = new THREE.SphereGeometry(500, 40, 24);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      top: { value: new THREE.Color('#2e5f9e') },
      mid: { value: new THREE.Color('#8fb8dd') },
      horizon: { value: new THREE.Color('#ffd9a0') },
      sunColor: { value: new THREE.Color('#fff3c4') },
      sunDir: { value: new THREE.Vector3(-0.45, 0.34, -0.85).normalize() },
    },
    vertexShader: /* glsl */ `
      varying vec3 vDir;
      void main() {
        vDir = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 top;
      uniform vec3 mid;
      uniform vec3 horizon;
      uniform vec3 sunColor;
      uniform vec3 sunDir;
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        float h = d.y;
        vec3 col = mix(horizon, mid, smoothstep(0.02, 0.30, h));
        col = mix(col, top, smoothstep(0.25, 0.75, h));
        vec3 below = mix(horizon, vec3(0.16, 0.32, 0.38), 0.6);
        col = mix(col, below, smoothstep(0.02, 0.20, -h));
        float s = clamp(dot(d, normalize(sunDir)), 0.0, 1.0);
        col += sunColor * pow(s, 600.0) * 1.3; // sun disc
        col += sunColor * pow(s, 24.0) * 0.30; // tight halo
        col += sunColor * pow(s, 3.0) * 0.10; // wide warm haze
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  return { mesh, sunDir: mat.uniforms.sunDir.value };
}

import * as THREE from 'three';

// Plan outline of the surfboard (nose at +y before rotation).
function boardShape() {
  const s = new THREE.Shape();
  s.moveTo(0, -1.55); // tail
  s.quadraticCurveTo(0.42, -1.35, 0.46, -0.6);
  s.quadraticCurveTo(0.5, 0.2, 0.3, 0.9);
  s.quadraticCurveTo(0.18, 1.38, 0, 1.62); // nose tip
  s.quadraticCurveTo(-0.18, 1.38, -0.3, 0.9);
  s.quadraticCurveTo(-0.5, 0.2, -0.46, -0.6);
  s.quadraticCurveTo(-0.42, -1.35, 0, -1.55);
  return s;
}

export function createSurfboard() {
  const group = new THREE.Group();
  const deckY = 0.13; // height of the standing surface above the group origin

  const geo = new THREE.ExtrudeGeometry(boardShape(), {
    depth: 0.12,
    steps: 1,
    bevelEnabled: true,
    bevelThickness: 0.03,
    bevelSize: 0.04,
    bevelSegments: 2,
  });
  geo.rotateX(Math.PI / 2); // plan shape -> XZ plane, nose toward +Z

  // bend in a little nose/tail rocker
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const z = pos.getZ(i);
    const lift =
      0.12 * Math.pow(Math.max(0, z) / 1.62, 2) +
      0.05 * Math.pow(Math.max(0, -z) / 1.55, 2);
    pos.setY(i, pos.getY(i) + lift);
  }

  const mat = new THREE.MeshStandardMaterial({
    color: '#e2574c',
    flatShading: true,
    roughness: 0.4,
  });
  const board = new THREE.Mesh(geo, mat);
  board.position.y = 0.09; // sit slightly into the waterline
  group.add(board);

  // deck stripes
  const stripeMat = new THREE.MeshStandardMaterial({
    color: '#f7ecd2',
    flatShading: true,
    roughness: 0.5,
  });
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.02, 2.2), stripeMat);
  stripe.position.set(0, deckY + 0.005, 0.05);
  group.add(stripe);
  const stripe2 = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.02, 1.7), stripeMat);
  stripe2.position.set(0.14, deckY + 0.005, 0);
  group.add(stripe2);

  // tail fin
  const fin = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.3, 0.22), mat);
  fin.position.set(0, -0.12, -1.28);
  fin.rotation.x = 0.3;
  group.add(fin);

  return { group, deckY };
}

import * as THREE from 'three';

const UP = new THREE.Vector3(0, 1, 0);
const STANCE = 0.95; // sideways surf stance (radians)

// Oriented cylinder between two points.
function makeLimb(a, b, radius, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius * 0.75, radius, len, 7);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.quaternion.setFromUnitVectors(UP, dir.normalize());
  return mesh;
}

// Wing plan outline (span outward in x, leading edge at +y -> +Z after rotation).
function wingShape(mirror) {
  const m = mirror ? -1 : 1;
  const s = new THREE.Shape();
  s.moveTo(0, 0.2);
  s.quadraticCurveTo(0.35 * m, 0.3, 0.62 * m, 0.14);
  s.quadraticCurveTo(0.75 * m, 0.02, 0.8 * m, -0.15);
  s.quadraticCurveTo(0.55 * m, -0.32, 0.28 * m, -0.3);
  s.quadraticCurveTo(0.1 * m, -0.34, 0, -0.24);
  s.closePath();
  return s;
}

export function createPelican() {
  const group = new THREE.Group(); // origin at deck level

  const bodyMat = new THREE.MeshStandardMaterial({ color: '#f6f1e3', flatShading: true, roughness: 0.85 });
  const wingMat = new THREE.MeshStandardMaterial({ color: '#b6c0cb', flatShading: true, roughness: 0.8 });
  const darkMat = new THREE.MeshStandardMaterial({ color: '#39424f', flatShading: true, roughness: 0.75 });
  const beakMat = new THREE.MeshStandardMaterial({ color: '#f0a132', flatShading: true, roughness: 0.55 });
  const pouchMat = new THREE.MeshStandardMaterial({ color: '#f7bd63', flatShading: true, roughness: 0.6 });
  const legMat = new THREE.MeshStandardMaterial({ color: '#e59a40', flatShading: true, roughness: 0.7 });
  const eyeMat = new THREE.MeshStandardMaterial({ color: '#1d222b', roughness: 0.25 });
  const glintMat = new THREE.MeshBasicMaterial({ color: '#ffffff' });

  // ---- feet planted on the deck (surf stance, toes toward the body's facing) ----
  const feet = [
    { x: 0.1, z: -0.48, rot: 1.25 }, // back foot
    { x: -0.12, z: 0.34, rot: 0.95 }, // front foot
  ];
  for (const f of feet) {
    const foot = new THREE.Group();
    const sole = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.045, 0.22), legMat);
    foot.add(sole);
    for (let i = -1; i <= 1; i++) {
      const toe = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.03, 0.15), legMat);
      toe.position.set(i * 0.05, -0.004, 0.145);
      toe.rotation.y = i * 0.3;
      foot.add(toe);
    }
    foot.position.set(f.x, 0.026, f.z);
    foot.rotation.y = f.rot;
    group.add(foot);
  }

  // ---- torso ----
  const bodyGroup = new THREE.Group();
  bodyGroup.position.set(0, 0.82, -0.05);
  bodyGroup.rotation.y = STANCE;
  group.add(bodyGroup);

  const body = new THREE.Mesh(new THREE.SphereGeometry(0.42, 18, 12), bodyMat);
  body.scale.set(0.95, 0.82, 1.3);
  bodyGroup.add(body);

  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.3, 14, 10), bodyMat);
  chest.position.set(0, -0.03, 0.3);
  chest.scale.set(0.92, 0.86, 1.05);
  bodyGroup.add(chest);

  const tail = new THREE.Mesh(new THREE.ConeGeometry(0.15, 0.5, 6), wingMat);
  tail.position.set(0, 0.1, -0.58);
  tail.rotation.x = -Math.PI / 2 + 0.55; // points back and up
  bodyGroup.add(tail);

  // ---- legs (static; thighs hidden inside the body) ----
  for (const [hipX, foot] of [
    [0.11, feet[0]],
    [-0.11, feet[1]],
  ]) {
    const hip = new THREE.Vector3(hipX, 0, -0.06)
      .applyAxisAngle(UP, STANCE)
      .add(new THREE.Vector3(0, 0, -0.05));
    hip.y = 0.56;
    group.add(makeLimb(new THREE.Vector3(foot.x, 0.05, foot.z), hip, 0.048, legMat));
  }

  // ---- neck & head ----
  const neckGroup = new THREE.Group();
  neckGroup.position.set(0, 0.28, 0.34);
  bodyGroup.add(neckGroup);

  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0.02, 0.02),
    new THREE.Vector3(0, 0.17, 0.1),
    new THREE.Vector3(0, 0.34, 0.12),
    new THREE.Vector3(0, 0.47, 0.1),
  ]);
  neckGroup.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 12, 0.115, 8), bodyMat));

  const headGroup = new THREE.Group();
  headGroup.position.set(0, 0.5, 0.1);
  headGroup.rotation.y = -STANCE + 0.15; // look down the line of travel
  neckGroup.add(headGroup);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.165, 14, 10), bodyMat);
  head.scale.set(0.95, 0.9, 1.05);
  headGroup.add(head);

  const tuft = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.15, 5), wingMat);
  tuft.position.set(0, 0.15, -0.05);
  tuft.rotation.x = -0.55;
  headGroup.add(tuft);

  for (const s of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.032, 8, 6), eyeMat);
    eye.position.set(s * 0.105, 0.045, 0.112);
    headGroup.add(eye);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.011, 6, 4), glintMat);
    glint.position.set(s * 0.115, 0.062, 0.132);
    headGroup.add(glint);
  }

  // ---- beak with pouch ----
  const beakGroup = new THREE.Group();
  beakGroup.position.set(0, -0.005, 0.1);
  headGroup.add(beakGroup);

  const upper = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.62, 5), beakMat);
  upper.scale.set(1.5, 1, 0.45); // scale, then rotate: flat wide blade
  upper.rotation.x = Math.PI / 2;
  upper.position.set(0, 0.02, 0.3);
  beakGroup.add(upper);

  const pouchGroup = new THREE.Group();
  pouchGroup.position.set(0, -0.02, 0.02);
  beakGroup.add(pouchGroup);

  const pouch = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 8), pouchMat);
  pouch.scale.set(1.15, 1.05, 3.4);
  pouch.position.set(0, -0.05, 0.3);
  pouchGroup.add(pouch);

  // ---- wings ----
  function buildWing(mirror) {
    const pivot = new THREE.Group(); // shoulder: sweep + slight incidence
    pivot.position.set((mirror ? -1 : 1) * 0.3, 0.16, -0.02);
    pivot.rotation.y = (mirror ? -1 : 1) * 0.16;
    pivot.rotation.x = 0.05;

    const flap = new THREE.Group(); // animated flapping axis
    pivot.add(flap);

    const geo = new THREE.ExtrudeGeometry(wingShape(mirror), {
      depth: 0.055,
      steps: 1,
      bevelEnabled: true,
      bevelThickness: 0.015,
      bevelSize: 0.02,
      bevelSegments: 1,
    });
    const mesh = new THREE.Mesh(geo, wingMat);
    mesh.rotation.x = Math.PI / 2; // +y leading edge -> +Z forward
    flap.add(mesh);

    // dark primary feathers at the trailing tip
    for (let i = 0; i < 3; i++) {
      const sgn = mirror ? -1 : 1;
      const feather = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.02, 0.08), darkMat);
      feather.position.set(sgn * (0.5 + i * 0.09), -0.005, -0.13 - i * 0.05);
      feather.rotation.y = sgn * -0.4;
      flap.add(feather);
    }
    bodyGroup.add(pivot);
    return flap;
  }

  const wingR = buildWing(false);
  const wingL = buildWing(true);

  // ---- animation ----
  function update(t, dt, state) {
    const { roll, pitch } = state;
    const crouch = Math.min(0.16, Math.abs(roll) * 0.35);

    bodyGroup.position.y = 0.82 + Math.sin(t * 2.1) * 0.045 - crouch;
    bodyGroup.rotation.z = roll * 1.15 + Math.sin(t * 1.4) * 0.02; // lean into carves
    bodyGroup.rotation.x = 0.09 + pitch * 0.6 + Math.sin(t * 2.6) * 0.03;

    // wings: mostly gliding, with occasional flapping bursts
    const burst = Math.pow(Math.max(0, Math.sin(t * 0.5 + 1.3)), 2);
    const flap = 0.16 + Math.sin(t * 2.7) * 0.06 + burst * (0.45 + 0.3 * Math.sin(t * 6.2));
    wingR.rotation.z = flap + Math.max(0, -roll) * 0.4;
    wingL.rotation.z = -(flap + Math.max(0, roll) * 0.4);

    tail.rotation.z = Math.sin(t * 2.3) * 0.12;
    tail.rotation.x = -Math.PI / 2 + 0.55 + Math.sin(t * 1.8) * 0.05;

    headGroup.rotation.x = Math.sin(t * 1.6) * 0.07 + pitch * 0.3;
    headGroup.rotation.z = Math.sin(t * 0.9) * 0.05 + roll * 0.35;

    // periodic pouch gulp
    const gulp = Math.pow(Math.max(0, Math.sin(t * 0.7)), 4);
    pouchGroup.rotation.x = gulp * 0.5;
    upper.rotation.x = Math.PI / 2 - gulp * 0.1;
    pouch.scale.set(1.15, 1.05 + gulp * 0.3, 3.4);
  }

  return { group, update };
}

import * as THREE from 'three';
import { waveHeight } from './water.js';

const MAX = 110;

// Droplets kicked off the nose and carving rail.
export function createSpray() {
  const geo = new THREE.IcosahedronGeometry(1, 0);
  const mat = new THREE.MeshStandardMaterial({
    color: '#ffffff',
    flatShading: true,
    roughness: 0.35,
    transparent: true,
    opacity: 0.88,
  });
  const mesh = new THREE.InstancedMesh(geo, mat, MAX);
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  mesh.frustumCulled = false;

  const pos = new Float32Array(MAX * 3);
  const vel = new Float32Array(MAX * 3);
  const life = new Float32Array(MAX);
  const maxLife = new Float32Array(MAX);
  const size = new Float32Array(MAX);
  const spin = [];
  for (let i = 0; i < MAX; i++) {
    spin.push(new THREE.Euler(Math.random() * 3, Math.random() * 3, Math.random() * 3));
  }

  const dummy = new THREE.Object3D();
  const hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  for (let i = 0; i < MAX; i++) {
    mesh.setMatrixAt(i, hidden);
  }
  life.fill(0);

  let cursor = 0;

  function spawn(x, y, z, vx, vy, vz) {
    const i = cursor;
    cursor = (cursor + 1) % MAX;
    pos[i * 3] = x;
    pos[i * 3 + 1] = y;
    pos[i * 3 + 2] = z;
    vel[i * 3] = vx;
    vel[i * 3 + 1] = vy;
    vel[i * 3 + 2] = vz;
    life[i] = maxLife[i] = 0.45 + Math.random() * 0.5;
    size[i] = 0.035 + Math.random() * 0.055;
  }

  function update(dt, t) {
    for (let i = 0; i < MAX; i++) {
      if (life[i] <= 0) continue;
      life[i] -= dt;
      vel[i * 3 + 1] -= 7.5 * dt; // gravity
      pos[i * 3] += vel[i * 3] * dt;
      pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
      pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
      if (life[i] <= 0 || pos[i * 3 + 1] < waveHeight(pos[i * 3], pos[i * 3 + 2], t) + 0.02) {
        life[i] = 0;
        mesh.setMatrixAt(i, hidden);
        continue;
      }
      const frac = 1 - life[i] / maxLife[i];
      const s = size[i] * Math.sin(Math.PI * frac) + 0.004;
      dummy.position.set(pos[i * 3], pos[i * 3 + 1], pos[i * 3 + 2]);
      dummy.rotation.copy(spin[i]);
      dummy.scale.setScalar(s);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
  }

  return { mesh, spawn, update };
}

import * as THREE from 'three';
import { waveHeight } from './water.js';

const MAX = 60;

// Expanding foam patches trailing behind the tail, riding the wave surface.
export function createWake() {
  const geo = new THREE.SphereGeometry(1, 8, 6);
  const mat = new THREE.MeshStandardMaterial({
    color: '#ffffff',
    flatShading: true,
    roughness: 0.55,
    transparent: true,
    opacity: 0.75,
  });
  const mesh = new THREE.InstancedMesh(geo, mat, MAX);
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  mesh.frustumCulled = false;

  const xs = new Float32Array(MAX);
  const zs = new Float32Array(MAX);
  const life = new Float32Array(MAX);
  const maxLife = new Float32Array(MAX);

  const dummy = new THREE.Object3D();
  const hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  const white = new THREE.Color('#ffffff');
  const waterCol = new THREE.Color('#39b7a9');
  const c = new THREE.Color();
  for (let i = 0; i < MAX; i++) {
    mesh.setMatrixAt(i, hidden);
    mesh.setColorAt(i, white);
    life[i] = 0;
  }

  let cursor = 0;

  function spawn(x, z) {
    const i = cursor;
    cursor = (cursor + 1) % MAX;
    xs[i] = x;
    zs[i] = z;
    life[i] = maxLife[i] = 2.4 + Math.random() * 0.9;
  }

  function update(dt, t) {
    for (let i = 0; i < MAX; i++) {
      if (life[i] <= 0) continue;
      life[i] -= dt;
      if (life[i] <= 0) {
        mesh.setMatrixAt(i, hidden);
        continue;
      }
      const frac = 1 - life[i] / maxLife[i];
      const fade = frac > 0.8 ? (1 - frac) / 0.2 : 1;
      const s = (0.16 + 0.95 * frac) * fade;
      dummy.position.set(xs[i], waveHeight(xs[i], zs[i], t) + 0.05, zs[i]);
      dummy.scale.set(s, Math.max(s * 0.2, 0.001), s);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
      c.copy(white).lerp(waterCol, frac * 0.85); // foam dissolving back into water
      mesh.setColorAt(i, c);
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  }

  return { mesh, spawn, update };
}

import * as THREE from 'three';

function wrap(v, range) {
  const r = range * 2;
  return ((v % r) + r) % r - range;
}

// Distant islands + drifting low-poly clouds.
export function createEnvironment() {
  const group = new THREE.Group();

  // ---- islands ----
  const islandA = new THREE.MeshStandardMaterial({ color: '#41626d', flatShading: true, roughness: 1 });
  const islandB = new THREE.MeshStandardMaterial({ color: '#4a6d78', flatShading: true, roughness: 1 });
  const mkIsland = (x, z, s, mat) => {
    const g = new THREE.Group();
    const cone = (r, h, px, pz, m) => {
      const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, 7), m);
      c.position.set(px, h * 0.5 - 1.6, pz);
      g.add(c);
    };
    cone(11 * s, 10 * s, 0, 0, mat);
    cone(7 * s, 6 * s, 9 * s, 4 * s, mat);
    cone(6 * s, 5 * s, -8 * s, 6 * s, islandB);
    g.position.set(x, -1.8, z);
    group.add(g);
  };
  mkIsland(-64, -80, 1.15, islandA);
  mkIsland(58, -98, 1.5, islandA);
  mkIsland(82, -24, 0.75, islandB);

  // ---- clouds (instanced puffs) ----
  const puffGeo = new THREE.SphereGeometry(1, 9, 7);
  const puffMat = new THREE.MeshStandardMaterial({ color: '#fdf6ec', flatShading: true, roughness: 1 });
  const CLOUDS = 7;
  const PER = 7;
  const N = CLOUDS * PER;
  const mesh = new THREE.InstancedMesh(puffGeo, puffMat, N);
  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  const data = [];
  let idx = 0;
  for (let cl = 0; cl < CLOUDS; cl++) {
    const cx = (Math.random() - 0.5) * 160;
    const cz = -35 - Math.random() * 95;
    const cy = 16 + Math.random() * 13;
    const spd = 0.6 + Math.random() * 0.8;
    const base = 1.5 + Math.random() * 2.2;
    for (let p = 0; p < PER; p++, idx++) {
      data.push({
        cx,
        cy,
        cz,
        spd,
        ox: (Math.random() - 0.5) * 6.5 * base,
        oy: (Math.random() - 0.5) * 1.2 * base,
        oz: (Math.random() - 0.5) * 2.6 * base,
        s: (0.45 + Math.random() * 0.8) * base,
      });
    }
  }
  group.add(mesh);

  const dummy = new THREE.Object3D();
  function update(t) {
    for (let i = 0; i < N; i++) {
      const d = data[i];
      const x = wrap(d.cx + t * d.spd, 90);
      dummy.position.set(x + d.ox, d.cy + d.oy, d.cz + d.oz);
      dummy.scale.set(d.s, d.s * 0.55, d.s * 0.85);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
  }
  update(0);

  return { group, update };
}

import * as THREE from 'three';

// Distant gulls circling on the breeze: tiny silhouettes with flapping wings.
export function createBirds() {
  const group = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: '#2c3a46', side: THREE.DoubleSide });

  const wingGeo = new THREE.BufferGeometry();
  wingGeo.setAttribute(
    'position',
    new THREE.Float32BufferAttribute([0, 0, -0.05, 1.15, 0.1, 0.32, 1.15, 0.1, -0.24], 3)
  );
  wingGeo.computeVertexNormals();

  const bodyGeo = new THREE.ConeGeometry(0.09, 0.6, 4);
  bodyGeo.rotateX(Math.PI / 2); // nose toward +Z

  const birds = [];
  for (let i = 0; i < 6; i++) {
    const b = new THREE.Group();
    b.add(new THREE.Mesh(bodyGeo, mat));
    const mkWing = (mirror) => {
      const pivot = new THREE.Group();
      const w = new THREE.Mesh(wingGeo, mat);
      if (mirror) w.rotation.y = Math.PI;
      pivot.add(w);
      b.add(pivot);
      return pivot;
    };
    const wr = mkWing(false);
    const wl = mkWing(true);
    b.scale.setScalar(0.7 + Math.random() * 0.8);
    group.add(b);
    birds.push({
      b,
      wr,
      wl,
      cx: (Math.random() - 0.5) * 60,
      cz: -25 - Math.random() * 70,
      r: 12 + Math.random() * 16,
      y: 6 + Math.random() * 8,
      w: (Math.random() < 0.5 ? -1 : 1) * (0.12 + Math.random() * 0.16),
      phase: Math.random() * Math.PI * 2,
      flap: 5.5 + Math.random() * 3,
    });
  }

  function update(t) {
    for (const d of birds) {
      const a = d.phase + t * d.w;
      d.b.position.set(
        d.cx + Math.cos(a) * d.r,
        d.y + Math.sin(t * 0.7 + d.phase) * 1.2,
        d.cz + Math.sin(a) * d.r
      );
      d.b.rotation.y = Math.atan2(-Math.sin(a) * d.w, Math.cos(a) * d.w);
      const f = Math.sin(t * d.flap + d.phase);
      d.b.rotation.z = f * 0.06;
      d.wr.rotation.z = f * 0.55;
      d.wl.rotation.z = -f * 0.55;
    }
  }

  return { group, update };
}

import * as THREE from 'three';
import { createSky } from './sky.js';
import { createWater, waveHeight } from './water.js';
import { createSurfboard } from './surfboard.js';
import { createPelican } from './pelican.js';
import { createSpray } from './spray.js';
import { createWake } from './wake.js';
import { createEnvironment } from './environment.js';
import { createBirds } from './birds.js';

// ---- renderer / scene / camera ----
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog('#ecd5a4', 65, 330);

const camera = new THREE.PerspectiveCamera(
  55,
  window.innerWidth / window.innerHeight,
  0.1,
  1600
);

// ---- sky & lights ----
const sky = createSky();
scene.add(sky.mesh);

const sun = new THREE.DirectionalLight('#ffdcae', 2.0);
sun.position.copy(sky.sunDir).multiplyScalar(90);
scene.add(sun);
scene.add(new THREE.HemisphereLight('#cfe8ff', '#0f5e6e', 0.75));

// ---- world ----
const water = createWater();
scene.add(water.mesh);

const environment = createEnvironment();
scene.add(environment.group);

const birds = createBirds();
scene.add(birds.group);

// ---- board + pelican ----
const boardGroup = new THREE.Group();
scene.add(boardGroup);
const surfboard = createSurfboard();
boardGroup.add(surfboard.group);
const pelican = createPelican();
pelican.group.position.y = surfboard.deckY;
boardGroup.add(pelican.group);

const spray = createSpray();
scene.add(spray.mesh);
const wake = createWake();
scene.add(wake.mesh);

// ---- board path (the pelican carves a lazy figure through the swell) ----
function boardPath(tt, out) {
  out.set(Math.sin(tt * 0.26) * 5.2, 0, Math.cos(tt * 0.21) * 3.8);
  return out;
}
function boardPathVel(tt, out = new THREE.Vector3()) {
  out.set(5.2 * 0.26 * Math.cos(tt * 0.26), 0, -3.8 * 0.21 * Math.sin(tt * 0.21));
  return out;
}

// ---- ride state ----
let t = 0;
let prevYaw = Math.atan2(boardPathVel(0).x, boardPathVel(0).z);
let rollS = 0;
let pitchS = 0;
let sprayAcc = 0;
let wakeTimer = 0;

const boardPos = new THREE.Vector3();
const boardVel = new THREE.Vector3();
const euler = new THREE.Euler(0, 0, 0, 'YXZ');
const dummy = new THREE.Object3D();
const camPos = new THREE.Vector3(9, 4.5, 9);
const camTarget = new THREE.Vector3();
const desired = new THREE.Vector3();
const lookAt = new THREE.Vector3();

boardPath(0, boardPos);
camTarget.copy(boardPos);

window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ---- animation loop ----
const clock = new THREE.Clock();
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05);
  t += dt;

  water.update(t);
  environment.update(t);
  birds.update(t);

  // --- board rides the wave surface ---
  boardPath(t, boardPos);
  boardPathVel(t, boardVel);
  const px = boardPos.x;
  const pz = boardPos.z;
  boardPos.y = waveHeight(px, pz, t) + 0.02;

  const yaw = Math.atan2(boardVel.x, boardVel.z);
  let dyaw = yaw - prevYaw;
  while (dyaw > Math.PI) dyaw -= Math.PI * 2;
  while (dyaw < -Math.PI) dyaw += Math.PI * 2;
  const turnRate = dt > 0 ? dyaw / dt : 0;
  prevYaw = yaw;

  const fx = Math.sin(yaw);
  const fz = Math.cos(yaw);
  const sx = Math.cos(yaw);
  const sz = -Math.sin(yaw);
  const hA = waveHeight(px + fx * 0.8, pz + fz * 0.8, t);
  const hB = waveHeight(px - fx * 0.8, pz - fz * 0.8, t);
  const hR = waveHeight(px + sx * 0.55, pz + sz * 0.55, t);
  const hL = waveHeight(px - sx * 0.55, pz - sz * 0.55, t);
  const pitch = -Math.atan2(hA - hB, 1.6) * 0.75; // follow the wave face
  const lateral = Math.atan2(hR - hL, 1.1);
  const bank = THREE.MathUtils.clamp(turnRate * 0.85, -0.5, 0.5); // lean into turns
  const roll = lateral * 0.65 - bank;

  const k = 1 - Math.exp(-dt * 8);
  pitchS += (pitch - pitchS) * k;
  rollS += (roll - rollS) * k;

  boardGroup.position.copy(boardPos);
  euler.set(pitchS, yaw, rollS);
  boardGroup.quaternion.setFromEuler(euler);
  boardGroup.updateMatrixWorld(true);

  pelican.update(t, dt, { roll: rollS, pitch: pitchS, speed: boardVel.length(), turnRate });

  // --- spray off the nose & the carving rail ---
  const speed = boardVel.length();
  sprayAcc += dt * (2 + speed * 6 + Math.abs(turnRate) * 26);
  while (sprayAcc >= 1) {
    sprayAcc -= 1;
    dummy.position.set((Math.random() - 0.5) * 0.5, 0.12, 1.3 + Math.random() * 0.35);
    boardGroup.localToWorld(dummy.position);
    spray.spawn(
      dummy.position.x,
      dummy.position.y,
      dummy.position.z,
      boardVel.x * 0.55 + (Math.random() - 0.5) * 2.4,
      1.3 + Math.random() * 2.3,
      boardVel.z * 0.55 + (Math.random() - 0.5) * 2.4
    );
    if (Math.abs(turnRate) > 0.45) {
      const side = Math.sign(turnRate);
      dummy.position.set(side * 0.42, 0.06, 0.35);
      boardGroup.localToWorld(dummy.position);
      spray.spawn(
        dummy.position.x,
        dummy.position.y,
        dummy.position.z,
        boardVel.x * 0.3 + sx * side * 3.2,
        1.6 + Math.random() * 2.0,
        boardVel.z * 0.3 + sz * side * 3.2
      );
    }
  }
  spray.update(dt, t);

  // --- foam wake behind the tail ---
  wakeTimer += dt;
  if (wakeTimer > 0.07) {
    wakeTimer = 0;
    dummy.position.set((Math.random() - 0.5) * 0.25, 0, -1.35);
    boardGroup.localToWorld(dummy.position);
    wake.spawn(dummy.position.x, dummy.position.z);
  }
  wake.update(dt, t);

  // --- slow drifting cinematic camera, never dips under the waves ---
  const ang = t * 0.11;
  const rad = 8.6 + Math.sin(t * 0.073) * 1.6;
  const hgt = 3.2 + Math.sin(t * 0.09) * 0.9 + Math.max(0, Math.sin(t * 0.05)) * 1.3;
  desired.set(boardPos.x + Math.cos(ang) * rad, hgt, boardPos.z + Math.sin(ang) * rad);
  desired.y = Math.max(desired.y, waveHeight(desired.x, desired.z, t) + 0.9);
  camPos.lerp(desired, 1 - Math.exp(-dt * 2.2));
  camPos.y = Math.max(camPos.y, waveHeight(camPos.x, camPos.z, t) + 0.55);
  camTarget.lerp(boardPos, 1 - Math.exp(-dt * 4));
  camera.position.copy(camPos);
  lookAt.copy(camTarget);
  lookAt.y += 1.0;
  camera.lookAt(lookAt);

  renderer.render(scene, camera);
});

